// This file is generated by AI.

// 重命名编辑应用的测试: LSP 行列 -> 文本下标, 以及按文件分组。

import { describe, expect, it } from 'vitest';

import type { LspTextEdit } from './client';
import { applyTextEdits, offsetAt, renameFileEdits } from './rename';

/** 构造一个替换编辑 */
function edit(line: number, start: number, end: number, newText: string): LspTextEdit {
  return {
    range: {
      start: { line, character: start },
      end: { line, character: end },
    },
    newText,
  };
}

describe('offsetAt', () => {
  it('按行累加偏移', () => {
    const text = 'ab\ncd\n';
    expect(offsetAt(text, { line: 0, character: 0 })).toBe(0);
    expect(offsetAt(text, { line: 0, character: 2 })).toBe(2);
    expect(offsetAt(text, { line: 1, character: 0 })).toBe(3);
    expect(offsetAt(text, { line: 1, character: 2 })).toBe(5);
    expect(offsetAt(text, { line: 2, character: 0 })).toBe(6);
  });

  it('按 UTF-16 计数 (与 JS 字符串一致)', () => {
    // 中文与 emoji 在 UTF-16 中各占 1 / 2 个单元
    const text = '你好😀x';
    expect(offsetAt(text, { line: 0, character: 2 })).toBe(2);
    expect(offsetAt(text, { line: 0, character: 4 })).toBe(4);
    expect(offsetAt(text, { line: 0, character: 5 })).toBe(5);
  });
});

describe('applyTextEdits', () => {
  it('应用单条编辑', () => {
    expect(applyTextEdits('setVar:hp=1;', [edit(0, 7, 9, '生命')])).toBe('setVar:生命=1;');
  });

  it('应用同一行的多条编辑', () => {
    const text = 'label:start;\njumpLabel:start;';
    expect(applyTextEdits(text, [edit(0, 6, 11, '开局'), edit(1, 10, 15, '开局')])).toBe(
      'label:开局;\njumpLabel:开局;'
    );
  });

  it('乱序传入也能正确应用 (从后往前替换)', () => {
    const text = 'chara:你好 -speaker=chara;';
    // JS 字符串按 UTF-16 计数: `chara` 出现在 0..5 与 18..23
    const edits = [edit(0, 0, 5, '主角'), edit(0, 18, 23, '主角')];
    expect(applyTextEdits(text, [...edits].reverse())).toBe('主角:你好 -speaker=主角;');
  });

  it('保留未编辑部分 (含 CRLF)', () => {
    const text = 'say:你好 -when=hp;\r\nreturn:hp;';
    expect(applyTextEdits(text, [edit(0, 13, 15, '生命'), edit(1, 7, 9, '生命')])).toBe(
      'say:你好 -when=生命;\r\nreturn:生命;'
    );
  });
});

describe('renameFileEdits', () => {
  it('按文件分组并转换为系统路径', () => {
    const targets = renameFileEdits({
      changes: {
        'file:///c%3A/project/game/scene/1.txt': [edit(0, 6, 11, '开局')],
        'file:///C:/project/game/scene/2.txt': [edit(0, 10, 15, '开局')],
      },
    });

    expect(targets).toEqual([
      { path: 'C:\\project\\game\\scene\\1.txt', edits: [edit(0, 6, 11, '开局')] },
      { path: 'C:\\project\\game\\scene\\2.txt', edits: [edit(0, 10, 15, '开局')] },
    ]);
  });

  it('忽略非文件协议与空编辑', () => {
    expect(renameFileEdits({})).toEqual([]);
    expect(renameFileEdits({ changes: { 'https://example.com/x': [edit(0, 0, 1, 'a')] } })).toEqual([]);
  });
});
